INSERT INTO jurisdiction_regimes(jurisdiction_id,regime_type,regime_name,authority_name,licence_or_approval,summary,mandatory_review,evidence_reference,status,source_id,confidence_score,legal_basis,requirements) SELECT j.id,'Corporate','Company incorporation and registry','Corporate Affairs Commission','CAC registration','Company incorporation and corporate compliance are administered by the Nigeria Corporate Affairs Commission under CAMA 2020.',true,s.url,'Verified',s.id,95,'Companies and Allied Matters Act 2020','Registration, statutory filings and corporate records through CAC.' FROM jurisdictions j JOIN jurisdiction_sources s ON s.jurisdiction_id=j.id AND s.source_name='CAC Company Registration' WHERE j.iso_code='NG' AND NOT EXISTS (SELECT 1 FROM jurisdiction_regimes r WHERE r.jurisdiction_id=j.id AND r.regime_name='Company incorporation and registry');
INSERT INTO jurisdiction_regimes(jurisdiction_id,regime_type,regime_name,authority_name,licence_or_approval,summary,mandatory_review,evidence_reference,status,source_id,confidence_score,legal_basis,requirements) SELECT j.id,'Beneficial Ownership','Persons with Significant Control','Corporate Affairs Commission','PSC filing','Relevant Nigerian companies and LLPs are subject to PSC and beneficial ownership reporting requirements.',true,s.url,'Verified',s.id,95,'CAMA 2020 and PSC Regulations 2022','PSC information at incorporation, annual returns, amendments or prescribed events.' FROM jurisdictions j JOIN jurisdiction_sources s ON s.jurisdiction_id=j.id AND s.source_name='CAC PSC Regulations 2022' WHERE j.iso_code='NG' AND NOT EXISTS (SELECT 1 FROM jurisdiction_regimes r WHERE r.jurisdiction_id=j.id AND r.regime_name='Persons with Significant Control');
INSERT INTO jurisdiction_regimes(jurisdiction_id,regime_type,regime_name,authority_name,licence_or_approval,summary,mandatory_review,evidence_reference,status,source_id,confidence_score,legal_basis,requirements) SELECT j.id,'Investment','Investment promotion framework','Rwanda Development Board','Investment registration / applicable approvals','Rwanda has an investment promotion and facilitation framework administered through its investment institutions and applicable law.',true,s.url,'Verified',s.id,85,'Law on Investment Promotion and Facilitation','Project-specific licensing, registration and incentive analysis remains required.' FROM jurisdictions j JOIN jurisdiction_sources s ON s.jurisdiction_id=j.id AND s.source_name='RDB Investment Promotion Law' WHERE j.iso_code='RW' AND NOT EXISTS (SELECT 1 FROM jurisdiction_regimes r WHERE r.jurisdiction_id=j.id AND r.regime_name='Investment promotion framework');
INSERT INTO jurisdiction_regimes(jurisdiction_id,regime_type,regime_name,authority_name,licence_or_approval,summary,mandatory_review,evidence_reference,status,source_id,confidence_score,legal_basis,requirements) SELECT j.id,'Land & Property','Land acquisition and registration','South African land registration authorities','Deed registration','South Africa has a formal land registration and property-rights framework; transaction-specific title, municipal and sector requirements must be reviewed.',true,s.url,'Verified',s.id,90,'Constitutional property rights and land-registration framework','Title and encumbrance review, municipal clearances and deed registration may be required.' FROM jurisdictions j JOIN jurisdiction_sources s ON s.jurisdiction_id=j.id AND s.source_name='Invest South Africa Investor Roadmap' WHERE j.iso_code='ZA' AND NOT EXISTS (SELECT 1 FROM jurisdiction_regimes r WHERE r.jurisdiction_id=j.id AND r.regime_name='Land acquisition and registration');
INSERT INTO jurisdiction_regimes(jurisdiction_id,regime_type,regime_name,authority_name,licence_or_approval,summary,mandatory_review,evidence_reference,status,source_id,confidence_score,legal_basis,requirements) SELECT j.id,'Foreign Investment','Foreign investment and sector controls','South African investment authorities','Transaction-specific approvals','South Africa generally encourages foreign investment, while sector-specific laws and transformation requirements can affect transactions and operating structures.',true,s.url,'Verified',s.id,88,'Protection of Investment Act 2015 and sector legislation','Assess sector restrictions, B-BBEE implications, tax registration and transaction-specific requirements.' FROM jurisdictions j JOIN jurisdiction_sources s ON s.jurisdiction_id=j.id AND s.source_name='Invest South Africa Foreign Investment Regime' WHERE j.iso_code='ZA' AND NOT EXISTS (SELECT 1 FROM jurisdiction_regimes r WHERE r.jurisdiction_id=j.id AND r.regime_name='Foreign investment and sector controls');