CREATE TABLE IF NOT EXISTS jurisdiction_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, source_name text NOT NULL, source_type text NOT NULL, url text, issuing_body text, publication_date date, accessed_date date NOT NULL DEFAULT current_date, effective_date date, expiry_date date, authority_level text NOT NULL DEFAULT 'Official', reliability_score integer NOT NULL DEFAULT 80, evidence_status text NOT NULL DEFAULT 'Verified', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jurisdiction_change_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jurisdiction_id uuid REFERENCES jurisdictions(id) ON DELETE CASCADE, regime_id uuid REFERENCES jurisdiction_regimes(id) ON DELETE SET NULL, change_type text NOT NULL, summary text NOT NULL, old_position text, new_position text, source_id uuid REFERENCES jurisdiction_sources(id), detected_date date NOT NULL DEFAULT current_date, effective_date date, impact_level text NOT NULL DEFAULT 'Medium', review_status text NOT NULL DEFAULT 'Pending');
ALTER TABLE jurisdiction_regimes ADD COLUMN IF NOT EXISTS source_id uuid REFERENCES jurisdiction_sources(id), ADD COLUMN IF NOT EXISTS confidence_score integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS effective_date date, ADD COLUMN IF NOT EXISTS review_date date, ADD COLUMN IF NOT EXISTS legal_basis text, ADD COLUMN IF NOT EXISTS restrictions text, ADD COLUMN IF NOT EXISTS requirements text, ADD COLUMN IF NOT EXISTS notes text;
ALTER TABLE jurisdiction_authorities ADD COLUMN IF NOT EXISTS source_id uuid REFERENCES jurisdiction_sources(id), ADD COLUMN IF NOT EXISTS website text;
ALTER TABLE jurisdiction_requirements ADD COLUMN IF NOT EXISTS jurisdiction_ref uuid REFERENCES jurisdictions(id), ADD COLUMN IF NOT EXISTS source_id uuid REFERENCES jurisdiction_sources(id), ADD COLUMN IF NOT EXISTS confidence_score integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS effective_date date, ADD COLUMN IF NOT EXISTS review_date date;
ALTER TABLE jurisdiction_reviews ADD COLUMN IF NOT EXISTS source_set_reference text, ADD COLUMN IF NOT EXISTS next_review_date date, ADD COLUMN IF NOT EXISTS confidence_score integer NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX IF NOT EXISTS uq_jis_source ON jurisdiction_sources(jurisdiction_id,source_name);
